'use strict';
const $=id=>document.getElementById(id),items=[{icon:'🍪',name:'바삭 쿠키',desc:'클릭 +1 P',base:20,type:'click',power:1},{icon:'🍔',name:'든든 버거',desc:'클릭 +5 P',base:140,type:'click',power:5},{icon:'🧋',name:'달콤한 버블티',desc:'초당 +1 P',base:75,type:'auto',power:1},{icon:'🍕',name:'피자 파티',desc:'초당 +6 P',base:520,type:'auto',power:6}];
let state={points:0,total:0,counts:[0,0,0,0],sound:true};try{const s=JSON.parse(localStorage.getItem('woojin-game-v1'));if(s&&Number.isFinite(s.points)&&s.counts?.length===4)state={...state,...s}}catch{}let selected=0,manual=false,audio,saveTimer,renderedPhoto='',bounce;
const thresholds=[0,40,160,450,1100,2500,5500,12000,26000,55000,115000,240000];const fmt=n=>Math.floor(n).toLocaleString('ko-KR');const power=t=>items.reduce((a,x,i)=>a+(x.type===t?x.power*state.counts[i]:0),t==='click'?1:0);const cost=i=>Math.ceil(items[i].base*1.19**state.counts[i]);function level(){let l=1;for(let i=1;i<thresholds.length;i++)if(state.total>=thresholds[i])l=i+1;return l}function save(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem('woojin-game-v1',JSON.stringify(state))}catch{}},200)}window.addEventListener('pagehide',()=>{try{localStorage.setItem('woojin-game-v1',JSON.stringify(state))}catch{}});
const photo=new Image();photo.src='photos.png';photo.onload=()=>draw(true);function draw(force=false){if(!photo.complete||!photo.naturalWidth)return;const l=level();if(!manual)selected=Math.min(2,Math.floor((l-1)/3));const key=l+':'+selected;if(!force&&renderedPhoto===key)return;renderedPhoto=key;const c=$('photo'),ctx=c.getContext('2d'),sw=photo.width/3,sh=photo.height,w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.drawImage(photo,sw*selected,0,sw,sh,0,0,w,h);const growth=Math.min(.42,(l-1)*.038);for(let y=400;y<h;y+=8){const v=Math.exp(-(((y-665)/135)**2))*growth;const expanded=w*(1+v);ctx.drawImage(photo,sw*selected,sh*y/h,sw,sh*8/h,(w-expanded)/2,y,expanded,8)}}
function sound(){if(!state.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.frequency.setValueAtTime(520,audio.currentTime);o.frequency.exponentialRampToValueAtTime(290,audio.currentTime+.065);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.08);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.08)}catch{}}
function celebrate(){const scene=$('scene'),b=document.createElement('div');b.className='levelburst';b.innerHTML='<strong>LEVEL UP!</strong><small>LV. '+level()+' · 우진이의 배가 자랐어요!</small>';scene.append(b);setTimeout(()=>b.remove(),1800);for(let i=0;i<30;i++){const p=document.createElement('i');p.className='confetti';p.style.setProperty('--color',['#ffce55','#ff8156','#fff7db','#89bc89'][i%4]);p.style.setProperty('--x',(Math.random()-.5)*550+'px');p.style.setProperty('--y',(Math.random()-.5)*650+'px');scene.append(p);setTimeout(()=>p.remove(),1400)}}
function gain(n){const old=level();state.points+=n;state.total+=n;if(level()>old){manual=false;celebrate()}render();save()}
function tap(x,y){gain(power('click'));sound();bounce?.cancel();bounce=$('photo').animate([{transform:'translateY(0) scale(1)'},{transform:'translateY(-5px) scale(1.016, .99)'},{transform:'translateY(2px) scale(.997,1.006)'},{transform:'translateY(0) scale(1)'}],{duration:240,easing:'ease-out'});const f=document.createElement('span'),r=$('scene').getBoundingClientRect();f.className='float';f.textContent='+'+fmt(power('click'));f.style.left=Math.max(8,Math.min(r.width-65,x-r.left))+'px';f.style.top=(y-r.top)+'px';$('scene').append(f);setTimeout(()=>f.remove(),900)}
$('character').addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();tap(e.clientX,e.clientY)});$('character').addEventListener('click',e=>{if(e.detail===0){const r=$('character').getBoundingClientRect();tap(r.left+r.width/2,r.top+r.height*.6)}});$('character').addEventListener('contextmenu',e=>e.preventDefault());
function render(){const l=level(),prev=thresholds[l-1],next=thresholds[l];$('points').textContent=fmt(state.points);$('level').textContent='LV. '+l;$('rank').textContent=['말랑말랑 새싹','간식 탐험가','통통한 행복','뱃살 마스터'][Math.min(3,Math.floor((l-1)/3))];$('clickstat').textContent='+'+fmt(power('click'))+' P';$('autostat').textContent=fmt(power('auto'))+' P / 초';$('perclick').textContent='터치당 +'+fmt(power('click'))+' P · 누적 '+fmt(state.total)+' P';$('progressText').textContent=next?fmt(state.total-prev)+' / '+fmt(next-prev)+' P':'MAX LEVEL';$('fill').style.width=next?Math.min(100,(state.total-prev)/(next-prev)*100)+'%':'100%';$('sound').textContent=state.sound?'♪':'♩';draw();$('photoTabs').innerHTML=['운동하는 우진','파워 우진','장난꾸러기 우진'].map((n,i)=>`<button data-photo="${i}" class="${i===selected?'selected':''}" ${l<i*3+1?'disabled':''}>${l<i*3+1?'🔒 LV.'+(i*3+1):n}</button>`).join('');items.forEach((x,i)=>{const b=$('upgrade'+i);b.disabled=state.points<cost(i);b.querySelector('.cost').innerHTML='✦ '+fmt(cost(i))+' P<small>보유 '+state.counts[i]+'</small>'})}
$('upgrades').innerHTML=items.map((x,i)=>`<button class="upgrade" id="upgrade${i}" data-i="${i}"><span class="uicon">${x.icon}</span><span class="utext"><strong>${x.name}</strong><small>${x.desc}</small></span><span class="cost"></span></button>`).join('');$('upgrades').onclick=e=>{const b=e.target.closest('button');if(!b)return;const i=+b.dataset.i,c=cost(i);if(state.points<c)return;state.points-=c;state.counts[i]++;sound();render();save()};$('photoTabs').onclick=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;selected=+b.dataset.photo;manual=true;render()};$('sound').onclick=()=>{state.sound=!state.sound;render();save()};$('reset').onclick=()=>{if(confirm('모든 포인트와 업그레이드를 초기화할까요?')){state={points:0,total:0,counts:[0,0,0,0],sound:state.sound};manual=false;render();save()}};let last=performance.now();setInterval(()=>{const now=performance.now(),dt=Math.min(2,(now-last)/1000);last=now;if(power('auto'))gain(power('auto')*dt)},250);render();
